import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // root object for this node
  const root = new Group();

  // geometry and material for the textured plane
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff });
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // load texture asynchronously; material will be updated when ready
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texturePromise.then((tex) => {
    material.map = tex;
    material.needsUpdate = true;
  });

  // keep references for cleanup
  const disposables = { geometry, material };
  const timelines = [];

  // apply any cinematic primitives defined in the config
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const handle = ctx.primitives[prim.name](root, prim.params);
      primitiveHandles.push(handle);
      if (handle.timeline) timelines.push(handle.timeline);
    }
  }

  // userData contract
  root.userData = {
    handlers: {}, // no interactions defined for this node
    cleanup() {
      // dispose geometry and material
      disposables.geometry?.dispose();
      disposables.material?.dispose();
      if (disposables.material?.map) disposables.material.map.dispose();

      // kill any GSAP timelines created by primitives or animations
      timelines.forEach((tl) => tl.kill());

      // invoke primitive cleanups
      primitiveHandles.forEach((h) => {
        if (typeof h.cleanup === 'function') h.cleanup();
      });
    },
  };

  return root;
}
